+func TestSQLiteRepositoryBackfillChatwootMessageLinkAccount(t *testing.T) {
+	repo := newTestSQLiteRepository(t)
+
+	legacyLink := &domainChatStorage.ChatwootMessageLink{
+		DeviceID:               "legacy-dev",
+		WhatsAppMessageID:      "legacy-1",
