+		Account:      chatwoot.Account{ID: 1},
+		Conversation: chatwoot.ConversationWebhook{ID: 5, InboxID: 9},
+	}, nil)
+	if route.DeviceID != "env-default-device" {
+		t.Fatalf("legacy mode should use env device, got %q", route.DeviceID)
+	}
+}
